         '--no-ext-diff',
         '--function-context',
         base,
@@ -82,7 +85,7 @@ export function createGit(root: string): Git {
       const added: string[] = []
       for (const path of untracked) {
         added.push(
-          await git(root, ['diff', '--no-color', '--no-index', '--', '/dev/null', path], [0, 1]),
